() => {
  const f = document.getElementById('flyer');
  const fb = f.getBoundingClientRect();
  const bad = [];
  f.querySelectorAll('*').forEach(el => {
    const r = el.getBoundingClientRect();
    if (r.left < fb.left - 0.5 || r.right > fb.right + 0.5 || r.top < fb.top - 0.5 || r.bottom > fb.bottom + 0.5)
      bad.push('OOB ' + el.className + ' ' + (el.textContent||'').slice(0,20) + ' ' + JSON.stringify([r.left-fb.left, r.top-fb.top, r.right-fb.right, r.bottom-fb.bottom].map(n=>+n.toFixed(1))));
    if (el.scrollWidth > el.clientWidth + 1 && getComputedStyle(el).overflow !== 'hidden')
      bad.push('HOVER ' + el.className + ' ' + el.scrollWidth + '>' + el.clientWidth);
  });
  return {size:[f.offsetWidth,f.offsetHeight], contentH: f.scrollHeight, photo: f.querySelector('.photo').getBoundingClientRect().height, bad,
    fonts: document.fonts.check('800 20px Inter')};
}

