async (page) => {
  const out = [];
  for (const [w,h,s] of [[1080,1350,1],[1200,1000,0.85],[300,600,0.28]]) {
    await page.goto(`http://localhost:60641/flyer.html?w=${w}&h=${h}&s=${s}`);
    await page.waitForTimeout(300);
    out.push(await page.evaluate(() => {
      const f = document.getElementById('flyer');
      const fb = f.getBoundingClientRect();
      const bad = [];
      const rects = [];
      f.querySelectorAll('*').forEach(el => {
        const r = el.getBoundingClientRect();
        if (r.width===0&&r.height===0) return;
        if (r.left < fb.left - 0.5 || r.right > fb.right + 0.5 || r.top < fb.top - 0.5 || r.bottom > fb.bottom + 0.5)
          bad.push('OOB ' + el.className);
        if (el.scrollWidth > el.clientWidth + 1) bad.push('OVERFLOW-X ' + el.className + ' ' + el.scrollWidth + '>' + el.clientWidth);
        if (el.scrollHeight > el.clientHeight + 1 && el.children.length===0) bad.push('OVERFLOW-Y ' + el.className);
        rects.push([el.className, +r.left.toFixed(1), +r.top.toFixed(1), +r.width.toFixed(1), +r.height.toFixed(1)]);
      });
      const cands = [...f.querySelectorAll('.cand')].map(c=>+c.getBoundingClientRect().width.toFixed(2));
      const bands = [...f.querySelectorAll('.photo,.cta')].map(c=>+c.getBoundingClientRect().width.toFixed(1));
      const img = f.querySelector('.photo');
      return {size:[f.offsetWidth,f.offsetHeight], bad, cands, bands,
        photoBox:[img.getBoundingClientRect().width, img.getBoundingClientRect().height],
        natural:[img.naturalWidth,img.naturalHeight],
        headLines: f.querySelector('.head').getBoundingClientRect().height / parseFloat(getComputedStyle(f.querySelector('.head')).lineHeight)};
    }));
  }
  return JSON.stringify(out, null, 1);
}

