  const out = [];
  const jobs = [[1080,1350,1,'portrait.png'],[1200,1000,0.85,'wide.png'],[300,600,0.28,'sky.png']];
  for (const [w,h,s,file] of jobs) {
    await page.goto(`http://localhost:60641/flyer.html?w=${w}&h=${h}&s=${s}`);
    await page.evaluate(() => document.fonts.ready);
    await page.waitForTimeout(400);
    const info = await page.evaluate(() => {
      const f = document.getElementById('flyer');
      const fb = f.getBoundingClientRect();
      const bad = [];
      f.querySelectorAll('*').forEach(el => {
        const r = el.getBoundingClientRect();
        if (r.width===0&&r.height===0) return;
        if (r.left < fb.left - 0.5 || r.right > fb.right + 0.5 || r.top < fb.top - 0.5 || r.bottom > fb.bottom + 0.5) bad.push('OOB ' + el.tagName + '.' + el.className);
        if (el.scrollWidth > el.clientWidth + 1) bad.push('OVX ' + el.tagName + '.' + el.className);
        if (el.scrollHeight > el.clientHeight + 1 && el.children.length===0) bad.push('OVY ' + el.tagName + '.' + el.className);
      });
      return {bad, cands:[...f.querySelectorAll('.cand')].map(c=>+c.getBoundingClientRect().width.toFixed(2)),
        size:[f.offsetWidth,f.offsetHeight]};
    });
    await page.locator('#flyer').screenshot({path: file, scale:'css', type:'png'});
    const buf = require('fs').readFileSync(file);
    const png = {w: buf.readUInt32BE(16), h: buf.readUInt32BE(20)};
    out.push({file, info, png});
  }
  return JSON.stringify(out);
}

